import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("matrix",...args);
export const matrixUtilsLessons=[
L("identity","Create and inspect basic matrices",[5, 6, 7, 8, 9],"<p>An identity matrix has diagonal ones; a null matrix has zeros. The predicates in this pinned core have quirks: <code>is_null()</code> insists on a square matrix, and <code>is_identity()</code> checks nonzero entries but does not require diagonal ones. Print the zero-matrix result to see that limitation.</p>","size = 2;\nidentity = $matrix_utils:identity(size);\nzero = $matrix_utils:null(size);\nplayer:tell(\"IDENTITY: \", toliteral(identity));\nplayer:tell(\"NULL: \", toliteral(zero));\nplayer:tell(\"IS SQUARE: \", toliteral($matrix_utils:is_square(identity)));\nplayer:tell(\"IS NULL: \", toliteral($matrix_utils:is_null(zero)));\nplayer:tell(\"IS IDENTITY zero limitation: \", toliteral($matrix_utils:is_identity(zero)));",edit("size = 2;","size = 3;","Increase the size to three. Both constructors produce three rows; the demonstrated predicate limitation remains.")),
L("shape","Validate shape before doing arithmetic",[14, 15, 21, 22],"<p>A vector is a numeric list. A matrix is a nonempty rectangular list of vectors. <code>dimensions()</code> follows the first branch; use <code>is_matrix()</code> to validate the other rows first. <code>order()</code> counts dimensions, not rows.</p>","m = {{1, 2}, {3, 4}};\nplayer:tell(\"IS VECTOR first row: \", toliteral($matrix_utils:is_vector(m[1])));\nplayer:tell(\"IS MATRIX: \", toliteral($matrix_utils:is_matrix(m)));\nplayer:tell(\"DIMENSIONS: \", toliteral($matrix_utils:dimensions(m)));\nplayer:tell(\"ORDER: \", toliteral($matrix_utils:order(m)));",edit("m = {{1, 2}, {3, 4}};","m = {{1, 2, 3}, {4, 5, 6}};","Use a two-by-three rectangle. Dimensions become {2, 3}, while its order stays 2.")),
L("vectors","Combine components and scale a vector",[0, 16],"<p>The shared vector definition chooses addition, subtraction, multiplication or division from the called alias. These are component-wise operations. Scalar helpers apply one number to each component; use matching numeric types and avoid zero divisors.</p>","v = {2, 4};\nw = {1, 2};\nplayer:tell(\"VECTOR add: \", toliteral($matrix_utils:vector_add(v, w)));\nplayer:tell(\"VECTOR subtract: \", toliteral($matrix_utils:vector_sub(v, w)));\nplayer:tell(\"VECTOR multiply: \", toliteral($matrix_utils:vector_mul(v, w)));\nplayer:tell(\"VECTOR divide: \", toliteral($matrix_utils:vector_div(v, w)));\nplayer:tell(\"SCALAR multiply: \", toliteral($matrix_utils:scalar_vector_mul(3, v)));\nplayer:tell(\"SCALAR add: \", toliteral($matrix_utils:scalar_vector_add(3, v)));\nplayer:tell(\"SCALAR subtract: \", toliteral($matrix_utils:scalar_vector_sub(1, v)));\nplayer:tell(\"SCALAR divide: \", toliteral($matrix_utils:scalar_vector_div(2, v)));",edit("v = {2, 4};","v = {4, 8};","Double the first vector. Compare each component-wise operation and notice that scalar addition does not simply double the old result.")),
L("transpose","Move between rows, columns and minors",[2, 12, 18],"<p>Transposition turns rows into columns. <code>column(matrix, index)</code> extracts a one-based column. <code>submatrix(row, column, matrix)</code> removes a row and column; it does not select a rectangular slice.</p>","m = {{1, 2}, {3, 4}};\nplayer:tell(\"TRANSPOSE: \", toliteral($matrix_utils:transpose(m)));\nplayer:tell(\"COLUMN second: \", toliteral($matrix_utils:column(m, 2)));\nplayer:tell(\"SUBMATRIX remove first row and column: \", toliteral($matrix_utils:submatrix(1, 1, m)));",edit("m = {{1, 2}, {3, 4}};","m = {{1, 2}, {3, 9}};","Change the bottom-right entry to nine. It appears in each transformed result.")),
L("dot","Compare dot product, length and angle",[13, 11, 17],"<p>The dot product is a scalar, not a vector of products. Norm is the floating length. The angle between nonzero vectors is returned in radians; zero vectors cannot define an angle.</p>","a = {3, 4};\nb = {3, 4};\nplayer:tell(\"DOT product: \", toliteral($matrix_utils:dot_prod(a, b)));\nplayer:tell(\"NORM a: \", toliteral($matrix_utils:norm(a)));\nplayer:tell(\"ANGLE radians: \", toliteral($matrix_utils:subtended_angle(a, b)));",edit("b = {3, 4};","b = {6, 8};","Scale the second vector by two. Dot product doubles, but the angle stays zero.")),
L("determinants","Compute a determinant and perpendicular vector",[3, 10],"<p>A two-by-two determinant is the signed area scale. A cross product takes two three-component vectors and returns a perpendicular vector. The aliases <code>outer_prod()</code> and <code>vector_prod()</code> here mean that same cross product, not a general tensor outer product.</p>","m = {{1, 2}, {3, 4}};\nplayer:tell(\"DETERMINANT: \", toliteral($matrix_utils:determinant(m)));\nplayer:tell(\"CROSS product: \", toliteral($matrix_utils:cross_prod({1, 0, 0}, {0, 1, 0})));",edit("{0, 1, 0}","{0, 2, 0}","Double the second cross-product vector. The resulting perpendicular vector doubles; the independent determinant is unchanged.")),
L("inverse","Multiply by an inverse",[4, 19],"<p>Use floating entries for fractional inverses. Integer division can truncate an inverse. A singular matrix has no inverse. Multiply the original by its computed inverse to inspect the identity result.</p>","m = {{2.0, 0.0}, {0.0, 4.0}};\ninverse = $matrix_utils:inverse(m);\nplayer:tell(\"INVERSE: \", toliteral(inverse));\nplayer:tell(\"PRODUCT: \", toliteral($matrix_utils:matrix_mul(m, inverse)));",edit("2.0, 0.0","4.0, 0.0","Change the first diagonal value to four. Its inverse becomes one quarter; the product is still the identity.")),
L("matrix-arithmetic","Add matrices and scale their entries",[1, 20],"<p>Matrix addition and subtraction work row by row; scalar multiplication and division apply to every entry. This core\u2019s add/subtract implementation calls List Utils slicing, which requires native threading controls. Use equally sized matrices.</p>","m = {{2, 4}, {6, 8}};\nn = {{1, 1}, {1, 1}};\nplayer:tell(\"MATRIX add: \", toliteral($matrix_utils:matrix_add(m, n)));\nplayer:tell(\"MATRIX subtract: \", toliteral($matrix_utils:matrix_sub(m, n)));\nplayer:tell(\"SCALAR MATRIX multiply: \", toliteral($matrix_utils:scalar_matrix_mul(2, m)));\nplayer:tell(\"SCALAR MATRIX divide: \", toliteral($matrix_utils:scalar_matrix_div(2, m)));",edit("{{1, 1}, {1, 1}}","{{2, 2}, {2, 2}}","Increase each entry of the second matrix to two. Addition increases and subtraction decreases accordingly; scalar operations use only the first matrix."),{"server": {"names": ["matrix_add", "scalar_matrix_mul"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore and native List Utils slicing."}}),
L("relations","Inspect the core\u2019s relation predicates",[23, 24, 25, 27],"<p>Relation matrices encode links as true entries. These are historical helpers, not reliable general mathematical validators: the shared result helper multiplies by a flag that is zero for the positive predicate names. Compare the positive and negative aliases before trusting their output. <code>is_partial_ordering()</code> also compares those results with chained equality.</p>","m = {{1, 0}, {0, 1}};\nplayer:tell(\"REFLEXIVE native behavior: \", toliteral($matrix_utils:is_reflexive(m)));\nplayer:tell(\"AREFLEXIVE native behavior: \", toliteral($matrix_utils:is_areflexive(m)));\nplayer:tell(\"SYMMETRIC native behavior: \", toliteral($matrix_utils:is_symmetric(m)));\nplayer:tell(\"ASYMMETRIC native behavior: \", toliteral($matrix_utils:is_asymmetric(m)));\nplayer:tell(\"TRANSITIVE native behavior: \", toliteral($matrix_utils:is_transitive(m)));\nplayer:tell(\"ATRANSITIVE native behavior: \", toliteral($matrix_utils:is_atransitive(m)));\nplayer:tell(\"PARTIAL ORDERING native behavior: \", toliteral($matrix_utils:is_partial_ordering(m)));",edit("{{1, 0}, {0, 1}}","{{0, 0}, {0, 0}}","Use the zero relation. Compare the raw predicate results against the earlier identity relation; the positive predicates still expose the implementation limitation.")),
L("movement-report","Build a vector movement report",[],"<p>Combine a position and displacement, then measure how far the displacement travels. Keep position, displacement and distance distinct: a position\u2019s norm is its distance from the origin, not distance traveled.</p>","position = {2, 1};\nstep = {3, 4};\nnext = $matrix_utils:vector_add(position, step);\nplayer:tell(\"START position: \", toliteral(position));\nplayer:tell(\"END position: \", toliteral(next));\nplayer:tell(\"DISTANCE traveled: \", toliteral($matrix_utils:norm(step)));",edit("step = {3, 4};","step = {6, 8};","Double the displacement. Travel distance doubles and the endpoint moves farther from the starting position.")),
];
export const matrixExclusions={"26": "Internal result helper shared by the relation predicates; their public lessons explicitly discuss its observed limitation."};
